M = [[-1, 0, 0], [0, -1, 0], [2, 0, -1]]
b = [1, 0, 0]
n = 3
for i in range(n):
    for j in range(i + 1, n):
        factor = M[j][i] / M[i][i]
        for k in range(i, n):
            M[j][k] -= factor * M[i][k]
        b[j] -= factor * b[i]
x = [0] * n
for i in range(n - 1, -1, -1):
    s = b[i]
    for j in range(i + 1, n):
        s -= M[i][j] * x[j]
    x[i] = s / M[i][i]
for v in x:
    print(round(v))
